def summarize_usage(events):
    max_usage = {}
    for event in events:
        request_id = event['request_id']
        input_val = event.get('input', 0)
        output_val = event.get('output', 0)

        if input_val < 0 or output_val < 0:
            raise ValueError("Token counts must be non-negative")

        if request_id not in max_usage:
            max_usage[request_id] = {'input': 0, 'output': 0}

        if input_val > max_usage[request_id]['input']:
            max_usage[request_id]['input'] = input_val
        if output_val > max_usage[request_id]['output']:
            max_usage[request_id]['output'] = output_val

    total_input = sum(usage['input'] for usage in max_usage.values())
    total_output = sum(usage['output'] for usage in max_usage.values())

    return {'input': total_input, 'output': total_output}

